import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Block","description":"","frontmatter":{},"headers":[],"relativePath":"components/block.md","filePath":"components/block.md"}'),r={name:"components/block.md"};function i(s,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="block" tabindex="-1">Block <a class="header-anchor" href="#block" aria-label="Permalink to &quot;Block&quot;">​</a></h1><p>Block is a wrapper with padding, for content that does not reach the edges of the container it sits in.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it inside a container without padding (a panel, a menu, a split column) to hold text, fields, name and value pairs and actions. Content that reaches the edges (lists, trees, tables, section headers) does not go in a Block, and a Block never sits directly in another container with padding.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>children</code></td><td>required</td><td>The content, usually a Stack</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The padding is <code>--kata-pad-md</code> on all sides and there is no surface or line. The first and the last line of text inside are trimmed to their ink, so the distance from the edge to the text is pad-md whether the content starts with text or a control. Inside it, stack with gap sm: the distance between neighbours must not exceed the distance to the edge.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/block/" title="Block" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/block/" target="_blank" rel="noopener">Block</a></figcaption></figure>',10)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
